// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

abstract contract FlagChallenge {
    string public challengeName;
    string private rewardFlag;
    mapping(address => bool) public solved;

    event FlagClaimed(address indexed player, string indexed challengeName);

    constructor(string memory name_, string memory flag_) {
        challengeName = name_;
        rewardFlag = flag_;
    }

    function claimFlag() external returns (string memory) {
        require(!solved[msg.sender], "already solved");
        require(_isSolved(msg.sender), "challenge not solved");

        solved[msg.sender] = true;
        emit FlagClaimed(msg.sender, challengeName);
        return rewardFlag;
    }

    function _isSolved(address player) internal view virtual returns (bool);
}


contract Game is FlagChallenge {
    mapping(address => uint256) public balanceOf;
    mapping(address => bool) public passed;

    constructor(string memory flag_) payable FlagChallenge("MediumReentrancyVault", flag_) {
        require(msg.value >= 1 ether, "seed with at least 1 ether");
    }

    function deposit() external payable {
        balanceOf[msg.sender] += msg.value;
    }

    function withdraw() external {
        uint256 amount = balanceOf[msg.sender];
        require(amount > 0, "no balance");

        (bool ok,) = msg.sender.call{value: amount}("");
        require(ok, "transfer failed");

        balanceOf[msg.sender] = 0;
    }

    function check() external {
        require(address(this).balance == 0, "vault still has ether");
        passed[msg.sender] = true;
    }

    function _isSolved(address player) internal view override returns (bool) {
        return passed[player];
    }
}
